/**
 * Single use. Returns false when the row was already consumed, so two
 * overlapping confirms cannot both change the password.
 */
export async function consumeResetToken(id: string): Promise<boolean> {
  const stamp = toIsoTimestamp(new Date());
  const rows = getDb()
    .update(passwordResetTokens)
    .set({ usedAt: stamp, updatedAt: stamp })
    .where(and(eq(passwordResetTokens.id, id), isNull(passwordResetTokens.usedAt)))
    .returning({ id: passwordResetTokens.id })
    .all();
  return rows.length > 0;
}

