import { beforeAll, afterAll, describe, expect, it, vi } from "vitest";
import { hashPassword } from "@/lib/hash";
import { resetRateLimits } from "@/lib/rate-limit";
import { getDb } from "@/server/db";
import { users } from "@/server/db/schema/users";
import * as userRepo from "@/server/repositories/user-repository";
import {
  confirmPasswordReset,
  login,
  requestPasswordReset,
} from "@/server/services/auth-service";
import {
  createSessionToken,
  destroySession,
  resolveSession,
} from "@/server/services/session-service";
import { useTemporaryDatabase } from "./server/_support/fixtures";
import { eq } from "drizzle-orm";

const sent: { to: string; html: string }[] = [];

vi.mock("@/server/services/email-service", () => ({
  renderEmail: async (_template: string, props: Record<string, unknown>) => ({
    subject: "reset",
    html: JSON.stringify(props),
    text: JSON.stringify(props),
  }),
  sendEmail: async (message: { to: string; html: string }) => {
    sent.push({ to: message.to, html: message.html });
  },
}));

const DAY = 24 * 60 * 60 * 1000;

function tokenFrom(html: string): string {
  const props = JSON.parse(html) as { token: string };
  return props.token;
}

describe("auth fixes", () => {
  let cleanup: () => void;

  beforeAll(async () => {
    cleanup = await useTemporaryDatabase();
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-06-01T00:00:00.000Z"));
  });

  afterAll(() => {
    vi.useRealTimers();
    cleanup?.();
  });

  it("covers sessions, resets, and per-address limits", async () => {
    resetRateLimits();
    const password = "Correct-horse-1";
    const userA = await userRepo.insertUser({
      email: "Ada@Example.com",
      name: "Ada",
      passwordHash: await hashPassword(password),
    });
    const userB = await userRepo.insertUser({
      email: "bob@example.com",
      name: "Bob",
      passwordHash: await hashPassword(password),
    });

    const short = await login({
      email: "ADA@example.com",
      password,
      rememberMe: false,
    });
    const shortPrincipal = await resolveSession(short.token);
    expect(shortPrincipal).not.toBeNull();
    expect(new Date(shortPrincipal!.expiresAt).getTime()).toBe(
      Date.now() + DAY,
    );

    const long = await login({
      email: "ada@example.com",
      password,
      rememberMe: true,
    });
    const longPrincipal = await resolveSession(long.token);
    expect(new Date(longPrincipal!.expiresAt).getTime()).toBe(
      Date.now() + 30 * DAY,
    );

    const bob = await login({
      email: "bob@example.com",
      password,
      rememberMe: false,
    });

    await destroySession(short.token);
    expect(await resolveSession(short.token)).toBeNull();
    expect(await resolveSession(long.token)).not.toBeNull();
    expect(await resolveSession(bob.token)).not.toBeNull();

    await destroySession("not-a-session");
    await destroySession(short.token);
    expect(await resolveSession(long.token)).not.toBeNull();

    const fresh = await createSessionToken(userA.id, false);
    expect(await resolveSession(fresh.token)).not.toBeNull();

    vi.setSystemTime(new Date(Date.now() + DAY));
    expect(await resolveSession(fresh.token)).toBeNull();
    expect(await resolveSession(long.token)).not.toBeNull();
    vi.setSystemTime(new Date(Date.now() + 29 * DAY));
    expect(await resolveSession(long.token)).toBeNull();
    expect(await resolveSession(bob.token)).toBeNull();

    vi.setSystemTime(new Date("2026-06-01T00:00:00.000Z"));
    resetRateLimits();

    const bobAgain = await login({
      email: "bob@example.com",
      password,
      rememberMe: true,
    });

    for (let i = 0; i < 30; i += 1) {
      await expect(
        login({ email: "ada@example.com", password: "wrong-password", rememberMe: false }),
      ).rejects.toThrow("Those credentials did not match");
    }
    await expect(
      login({ email: "ada@example.com", password, rememberMe: false }),
    ).rejects.toThrow("Too many sign-in attempts");
    const bobStill = await login({
      email: "BOB@example.com",
      password,
      rememberMe: false,
    });
    expect(bobStill.user.id).toBe(userB.id);

    sent.length = 0;
    resetRateLimits();
    await requestPasswordReset({ email: "nobody@example.com" });
    expect(sent).toHaveLength(0);

    await requestPasswordReset({ email: "Ada@Example.com" });
    await requestPasswordReset({ email: "ada@example.com" });
    expect(sent).toHaveLength(2);
    const firstLink = tokenFrom(sent[0]!.html);
    const secondLink = tokenFrom(sent[1]!.html);

    await requestPasswordReset({ email: "bob@example.com" });
    const bobLink = tokenFrom(sent[2]!.html);

    await expect(
      confirmPasswordReset({
        token: firstLink,
        password: "New-password-1",
        confirmPassword: "New-password-1",
      }),
    ).rejects.toThrow("no longer valid");

    const resetUser = await confirmPasswordReset({
      token: secondLink,
      password: "New-password-1",
      confirmPassword: "New-password-1",
    });
    expect(resetUser.id).toBe(userA.id);
    expect(await resolveSession(bobAgain.token)).not.toBeNull();

    await expect(
      login({ email: "ada@example.com", password, rememberMe: false }),
    ).rejects.toThrow("did not match");
    const adaNew = await login({
      email: "ada@example.com",
      password: "New-password-1",
      rememberMe: false,
    });
    expect(await resolveSession(adaNew.token)).not.toBeNull();

    await expect(
      confirmPasswordReset({
        token: secondLink,
        password: "Newer-password-2",
        confirmPassword: "Newer-password-2",
      }),
    ).rejects.toThrow("no longer valid");

    await confirmPasswordReset({
      token: bobLink,
      password: "Bob-password-2",
      confirmPassword: "Bob-password-2",
    });
    expect(await resolveSession(bobAgain.token)).toBeNull();
    expect(await resolveSession(bobStill.token)).toBeNull();
    expect(await resolveSession(adaNew.token)).not.toBeNull();

    sent.length = 0;
    resetRateLimits();
    vi.setSystemTime(new Date("2026-07-01T00:00:00.000Z"));
    await requestPasswordReset({ email: "ada@example.com" });
    const expiring = tokenFrom(sent[0]!.html);
    vi.setSystemTime(new Date(Date.now() + 60 * 60 * 1000 - 1000));
    await confirmPasswordReset({
      token: expiring,
      password: "Timed-password-3",
      confirmPassword: "Timed-password-3",
    });

    sent.length = 0;
    await requestPasswordReset({ email: "bob@example.com" });
    const expired = tokenFrom(sent[0]!.html);
    vi.setSystemTime(new Date(Date.now() + 60 * 60 * 1000));
    await expect(
      confirmPasswordReset({
        token: expired,
        password: "Timed-password-4",
        confirmPassword: "Timed-password-4",
      }),
    ).rejects.toThrow("no longer valid");

    sent.length = 0;
    resetRateLimits();
    vi.setSystemTime(new Date("2026-08-01T00:00:00.000Z"));
    for (let i = 0; i < 5; i += 1) {
      await requestPasswordReset({ email: "ada@example.com" });
    }
    expect(sent).toHaveLength(5);
    await requestPasswordReset({ email: "ada@example.com" });
    expect(sent).toHaveLength(5);
    await requestPasswordReset({ email: "bob@example.com" });
    expect(sent).toHaveLength(6);

    await getDb().update(users).set({ email: "Mixed@Example.com" }).where(eq(users.id, userB.id));
    resetRateLimits();
    const mixed = await login({
      email: "mixed@example.com",
      password: "Bob-password-2",
      rememberMe: false,
    });
    expect(mixed.user.email.toLowerCase()).toBe("mixed@example.com");
  });
});

